/* A classroom reconstruction using modern Z/T notation, not Gosset's original dataset. */
(()=>{'use strict';const M=TrialStoryModel,blue='#789db5',orange='#bf9250',green='#7e9f79',cache=new WeakMap();
const f=(v,d=2)=>Number(v).toFixed(d),button=(action,label,attrs='')=>`<button data-action="${action}" ${attrs}>${label}</button>`;
function summary(records){let out=cache.get(records);if(out?.count===records.length)return out;const pairs=records.map(M.pair),lo=-5.5,width=.25,bins=44,z=Array(bins).fill(0),r=Array(bins).fill(0);let zOutside=0,rOutside=0,zTails=0,rTails=0;
 for(const p of pairs){for(const [key,counts] of [['z',z],['r',r]]){const i=Math.floor((p[key]-lo)/width);if(i>=0&&i<bins)counts[i]++;else if(key==='z')zOutside++;else rOutside++;}if(Math.abs(p.z)>=2)zTails++;if(Math.abs(p.r)>=2)rTails++;}
 out={count:pairs.length,pairs,z,r,lo,width,zOutside,rOutside,zTails,rTails};cache.set(records,out);return out;
}
function discoveryMarkup(state){const e=state.e,s=summary(e.runs),last=s.pairs.at(-1),deviation=M.deviations(e.dfValues);
 let html=(s.count<1000?`<div class="activity-row">${button('variance','抽一组四个产量，分别计算','class="primary"')}</div>`:'')+`<p class="activity-meta">已比较 ${s.count} 组${s.count<1000?'；先逐组做至少3次。':'，先观察结果，再认识这条分布。'}${!e.tRevealed?'<br>橙色结果先暂记为R，先看它怎样分布。':''}</p>`;
 if(last)html+=`<div class="samples-chips">${e.runs.at(-1).map(v=>`<span>${f(v,1)}</span>`).join('')}</div><div class="paired-results"><div><small>同一均值 ${f(last.mean,1)}，已知分母 ${f(last.trueSE)}</small><b>Z＝${f(last.z)}</b></div><div><small>用这四个数估计分母 ${f(last.estimatedSE)}</small><b>${e.tRevealed?'T':'R'}＝${f(last.r)}</b></div></div>`;
 if(e.manualRuns>=3&&s.count<1000)html+=`<div class="activity-row">${button('discovery-many','继续做到1000次，看分布','class="primary"')}</div>`;
 if(s.count>=1000&&!e.tailCompared)html+=`<div class="teacher-note">我们数一数±2之外的结果：<br>蓝色Z：${f(s.zTails/s.count*100,1)}%<br>橙色R：${f(s.rTails/s.count*100,1)}%<br><b>哪一套结果的尾部更多？</b></div><div class="activity-row">${button('discovery-tail','已知分母的Z','data-value="z"')}${button('discovery-tail','估计分母后的R','data-value="r"')}</div>`;
 if(e.tailCompared&&!e.tRevealed)html+=`<div class="teacher-note">估计的分母有时偏小，把同样的均值偏离放大了。橙色结果的尾部比标准正态更多。我们需要描述它自己的分布。</div><div class="activity-row">${button('reveal-t','看看Gosset怎样描述这条分布','class="primary"')}</div>`;
 if(e.tRevealed)html+=`<div class="teacher-note">这类结果按现代记号服从 <b>Student t分布</b>。它还带着一个参数：自由度。我们先用四个偏差把这个词弄明白。</div><div class="df-workshop"><p>自由度示例：保持样本均值550。</p>${e.dfValues.map((d,i)=>`<label class="range-label">第${i+1}个偏差 <output id="dev-out-${i}">${d>0?'+':''}${d}</output><input type="range" min="-60" max="60" step="10" value="${d}" data-dev="${i}" aria-label="第${i+1}个偏差"></label>`).join('')}<div class="deviations" id="df-sum">${deviationMarkup(deviation)}</div><p>原始观测可以独立；减去同一个样本均值后，四个偏差的和必须是0。前三个能自由选，第4个只能补齐。</p><p id="df-touched">已调整 ${new Set(e.dfTouched).size} 个偏差；请至少改变其中两个。</p></div>`;
 html+=`<details class="activity-meta"><summary>Gosset当年怎样做？</summary>他把3000份测量资料写到卡片上，打乱后每4份分成一组，共750组，逐组计算并比较分布。这里换成玉米产量，用现代Z和T记号重现这种比较思路，数据为教学模拟。</details>`;return html;
}
function deviationMarkup(d){return d.map((v,i)=>`<span class="${i===3?'dependent':''}">${v>0?'+':''}${v}</span>`).join('')+'<b>＝0</b>';}
function comparisonMarkup(state,n){const c=M.convergence(n);return `<label class="range-label" for="compare-n">独立重复数 n <output id="n-out">${n}</output></label><label class="range-label"><input id="compare-n" type="range" min="4" max="100" step="1" value="${n}" aria-label="模拟样本量"></label><div class="range-presets">${[4,10,30,100].map(v=>button('compare-n',String(v),`data-n="${v}" class="${v===n?'active':''}"`)).join('')}</div><div id="comparison-numbers">${comparisonNumbers(c)}</div><div class="activity-row">${button('show-z',state.e.zObserved?'再看一次Z怎样换刻度':'Z也除以√n，为什么形状不变？','class="primary"')}</div>${state.e.zObserved?'<div class="teacher-note">均值原有的波动是σ/√n，分母也正好是σ/√n；一起缩放后，Z的标准差总是1。<br><b>T＝Z×σ/s</b> 还带着随机的σ/s。s对σ的估计随自由度n−1变化，T的形状和尾部概率也随之改变。</div>':''}<div class="teacher-note">n越大，s对σ的估计越稳定，s/√n相对σ/√n的误差通常越小。<b>总体标准误差σ/√n仍在减小</b>；有限样本的估计不保证与它完全相等。</div>`;}
function comparisonNumbers(c){return `<div class="numeric-grid"><div><small>总体σ＝40保持不变</small><b>df＝${c.df}</b></div><div><small>总体SE＝40/√${c.n}</small><b>${f(c.trueSE)}</b></div><div><small>位置2右侧 · 标准正态</small><b>${f(c.zTail*100,2)}<em>%</em></b></div><div><small>位置2右侧 · t<sub>${c.df}</sub></small><b>${f(c.tTail*100,2)}<em>%</em></b></div></div>`;}
function axis(w){const X=x=>x*12/11,Y=p=>p*7.5;w.line([[-6.1,0,0],[6.2,0,0]],'#91a081',1);for(const x of [-4,-2,0,2,4])w.label([X(x),-.3,0],String(x),{size:11,color:'#778b68'});for(const x of [-2,2])w.line([[X(x),0,0],[X(x),3.3,0]],'#c0cbb2',.8,{dash:[3,5]});return {X,Y};}
function discovery(w,v){w.extent=16;w.target=w.width<600?3:1.7;const {X,Y}=axis(w),e=v.session.e,s=summary(e.runs),n=Math.max(1,s.count),hist=s.count>=20;
 if(hist){for(let i=0;i<s.z.length;i++){const x=s.lo+i*s.width,bw=s.width*12/11;for(const [counts,color,dz] of [[s.z,blue,-.035],[s.r,orange,.035]]){const height=counts[i]/(n*s.width)*7.5;if(height)w.box(X(x+s.width/2),0,dz,bw*.9,height,.035,color,{alpha:.45});}}}
 else for(const p of s.pairs){w.dot([X(p.z),.12,-.025],.06,blue);w.dot([X(p.r),.21,.025],.06,orange);w.line([[X(p.z),.12,0],[X(p.r),.21,0]],'#c6b589',.7,{alpha:.5});}
 const line=(fn,color,dash=[])=>w.line(Array.from({length:181},(_,i)=>{const x=-5.5+i/180*11;return [X(x),Y(fn(x)),0]}),color,1.9,{dash});line(NormalMath.pdf,blue,[4,4]);if(e.tRevealed)line(x=>StudentTMath.pdf(x,3),orange);
 w.label([-3.2,3.75,0],'蓝：已知总体标准误差 → Z',{size:11,color:blue});w.label([3.0,3.75,0],e.tRevealed?'橙：估计标准误差 → T':'橙：估计标准误差 → R',{size:11,color:orange});
 if(hist){w.label([-2.8,-.8,0],`±2外：Z ${f(s.zTails/n*100,1)}%`,{size:11,color:blue,pill:true});w.label([2.8,-.8,0],`±2外：${e.tRevealed?'T':'R'} ${f(s.rTails/n*100,1)}%`,{size:11,color:orange,pill:true});}
 if(e.tRevealed)w.label([0,-1.3,0],new Set(e.dfTouched).size>=2?'四个偏差，一个和为0的约束 → df＝3':'拖动右侧偏差，看第4个怎样补齐',{size:11,color:'#7a8b66'});
 w.canvas.dataset.discoveryCount=String(s.count);w.canvas.dataset.tCurveVisible=String(e.tRevealed);w.canvas.dataset.discoveryOutside=String(s.zOutside+s.rOutside);
}
function paintComparison(w,v){if(!v.session.e.zObserved&&!v.zShowing)return;const c=w.ctx,mobile=w.width<600,cw=Math.min(w.width-36,700),ch=mobile?180:176,x=(w.width-cw)/2,y=w.height-260,p=v.zVisual??1,left=x+cw*.25,right=x+cw*.76,half=cw*.17;
 c.save();c.fillStyle='#fffdf0ef';c.strokeStyle='#dce3cb';c.beginPath();c.roundRect(x,y,cw,ch,10);c.fill();c.stroke();c.font=`${mobile?9:11}px Microsoft YaHei,sans-serif`;c.fillStyle='#788a68';c.textAlign='center';c.fillText('原来的均值波动',left,y+20);c.fillText('除以各自的SE后',right,y+20);
 [4,16,64].forEach((n,i)=>{const yy=y+44+i*28,se=40/Math.sqrt(n),raw=half*se/20;c.strokeStyle=blue;c.beginPath();c.moveTo(left-raw,yy);c.lineTo(left+raw,yy);c.stroke();c.strokeStyle='#86a67a';c.beginPath();c.moveTo(right-half,yy);c.lineTo(right+half,yy);c.stroke();c.fillStyle='#829370';c.textAlign='left';c.fillText(`n=${n}`,x+8,yy+3);for(const sign of [-1,1]){c.fillStyle=blue;c.beginPath();c.arc((left+sign*raw)*(1-p)+(right+sign*half)*p,yy,2.8,0,7);c.fill();}c.textAlign='center';c.fillText('−1        +1',right,yy+13);});
 const con=M.convergence(v.compareN),base=y+ch-25;for(const [n,yy] of [[4,base-19],[v.compareN,base]]){const data=M.convergence(n);c.strokeStyle='#d1dac2';c.beginPath();c.moveTo(x+70,yy);c.lineTo(x+cw-15,yy);c.stroke();const X=r=>x+70+Math.max(0,Math.min(2,r))/2*(cw-85);for(let i=0;i<data.ratios.length;i++){c.fillStyle='#ba945866';c.beginPath();c.arc(X(data.ratios[i]),yy+(i%5-2)*1.2,1.4,0,7);c.fill();}c.fillStyle='#81916d';c.textAlign='left';c.fillText(`s/σ n=${n}`,x+8,yy+3);c.strokeStyle=green;c.beginPath();c.moveTo(X(1),yy-7);c.lineTo(X(1),yy+7);c.stroke();}c.restore();w.canvas.dataset.knownZShape='N(0,1)';w.canvas.dataset.relativeSEError=String(con.relativeRMSE);
}
function dashboardMarkup(state){const e=state.e,data=M.stats(M.noisy),choice=state.answers.challenge,ok=M.correct(state,'challenge');return `<section class="summary-card summary-field"><h3>① 收获新一批四个小区</h3><div id="summary-field-host"></div><div class="summary-yields">${M.noisy.map((v,i)=>button('new-plot',e.newHarvest.includes(i)?`重复${i+1} · ${v}`:`收获重复${i+1}`,`data-plot="${i}" ${e.newHarvest.includes(i)?'disabled class="collected"':''}`)).join('')}</div><small>亩产单位：公斤/亩 · 小区图可拖动旋转</small></section><section class="summary-card"><h3>② 平均值与标准误差</h3>${e.noisy?`<div class="summary-stat"><span>x̄＝${f(data.mean,0)}</span><span>s＝${f(data.s)}</span><span>SE＝${f(data.se)}</span></div><p>均值仍为550；四个小区更分散。</p><p>前一批SE≈12.91<br>这一批SE≈25.82</p>`:`<p>先完成四个小区的收获。</p>${button('noisy','计算本批均值和标准误差',`${e.newHarvest.length<4?'disabled':''} class="primary"`)}`}</section><section class="summary-card summary-probability"><h3>③ 在t分布上找位置与概率</h3><canvas id="summary-curve" aria-label="新一批试验的t分布与右尾概率"></canvas><div class="summary-prob-label">${e.noisy?`t＝(550−500)/25.82≈1.94<br>df＝3，右尾p≈${f(data.p,3)}（延伸至＋∞）`:'用这批数据的SE换成t坐标，再计算右尾面积。'}</div></section><section class="summary-card summary-conclusion"><h3>④ 根据概率作出结论</h3>${e.noisy?`<div class="summary-comparison">p≈${f(data.p,3)} ＞ α＝0.05</div><p>${M.steps[14].question}</p><div class="summary-choices">${M.steps[14].options.map(([id,text])=>button('summary-answer',text,`data-value="${id}" class="${choice===id?(ok?'correct':'wrong'):''}" ${ok?'disabled':''}`)).join('')}</div>${choice?`<p class="summary-result">${ok?'尚未发现显著提高的证据。平均值相同，分散程度不同，结论可能不同。':'请再比较右尾概率与0.05。'}</p>`:''}`:'先用本批数据算出概率，再和试验前约定的0.05比较。'}</section>`;}
function paintDashboard(canvas,state){if(!canvas)return;const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;const dpr=Math.min(devicePixelRatio||1,2),w=r.width,h=r.height;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);const data=M.stats(M.noisy),X=x=>25+(x+4.5)/9*(w-45),Y=p=>h-24-p*(h-45)/.42,base=Y(0);c.clearRect(0,0,w,h);c.strokeStyle='#bccbad';c.beginPath();c.moveTo(20,base);c.lineTo(w-15,base);c.stroke();
 if(state.e.noisy){c.fillStyle='#c6a36a66';c.beginPath();c.moveTo(X(data.t),base);for(let i=0;i<=90;i++){const x=data.t+(4.5-data.t)*i/90;c.lineTo(X(x),Y(StudentTMath.pdf(x,3)));}c.lineTo(X(4.5),base);c.fill();c.strokeStyle=orange;c.setLineDash([3,4]);c.beginPath();c.moveTo(X(data.t),base);c.lineTo(X(data.t),22);c.stroke();c.setLineDash([]);c.fillStyle='#9c7f45';c.font='12px Georgia,serif';c.textAlign='center';c.fillText('t≈1.94',X(data.t),15);}
 c.beginPath();for(let i=0;i<=180;i++){const x=-4.5+i/180*9;i?c.lineTo(X(x),Y(StudentTMath.pdf(x,3))):c.moveTo(X(x),Y(StudentTMath.pdf(x,3)));}c.strokeStyle=orange;c.lineWidth=1.8;c.stroke();c.font='10px Georgia,serif';c.fillStyle='#80906c';c.textAlign='center';for(const x of [-4,-2,0,2,4])c.fillText(String(x),X(x),h-8);canvas.dataset.df='3';canvas.dataset.mean=String(data.mean);canvas.dataset.se=String(data.se);canvas.dataset.p=String(data.p);}
window.TrialStoryGosset={summary,discoveryMarkup,deviationMarkup,comparisonMarkup,comparisonNumbers,discovery,paintComparison,dashboardMarkup,paintDashboard};
})();
